                    investment: 20,
                    partner: 'solo',
                    orgDesign: 'separate',
                    changeSpeed: 'moderate',
                    commInvestment: 0
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var period = state.currentPeriod || 1;
            var read = function(id) {
                var el = document.getElementById(id);
                return el ? el.value : null;
            };
            var num = function(id) {
                var el = document.getElementById(id);
                return el ? parseFloat(el.value) : NaN;
            };

            if (period === 1) {
                decisions.rivalry = num('rivalryInput');
                decisions.buyer = num('buyerInput');
                decisions.supplier = num('supplierInput');
                decisions.substitute = num('substituteInput');
                decisions.entrants = num('entrantsInput');
                var forces = [decisions.rivalry, decisions.buyer, decisions.supplier, decisions.substitute, decisions.entrants];
                for (var i = 0; i < forces.length; i++) {
                    if (isNaN(forces[i]) || forces[i] < 1 || forces[i] > 10) {
                        window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_forces'), 'warning');
                        return false;
                    }
                }
            } else if (period === 2) {
                decisions.eliminate = read('eliminateInput');
                decisions.reduce = read('reduceInput');
                decisions.raise = read('raiseInput');
                decisions.create = read('createInput');
                if (!decisions.eliminate || !decisions.reduce || !decisions.raise || !decisions.create) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_actions'), 'warning');
                    return false;
                }
            } else if (period === 3) {
                decisions.tier = read('tierInput');
                decisions.segment = read('segmentInput');
                decisions.tam = num('tamInput');
                if (!decisions.tier || !decisions.segment || isNaN(decisions.tam) || decisions.tam < 10 || decisions.tam > 500) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_tier'), 'warning');
                    return false;
                }
            } else if (period === 4) {
                decisions.pricing = read('pricingInput');
                decisions.investment = num('investmentInput');
                decisions.partner = read('partnerInput');
                if (!decisions.pricing || !decisions.partner || isNaN(decisions.investment) || decisions.investment < 5 || decisions.investment > 60) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_bm'), 'warning');
                    return false;
                }
                if (decisions.investment > state.domainState.cash) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_cash'), 'warning');
                    return false;
                }
            } else if (period === 5) {
                decisions.orgDesign = read('orgInput');
                decisions.changeSpeed = read('speedInput');
                decisions.commInvestment = num('commInput');
                if (!decisions.orgDesign || !decisions.changeSpeed || isNaN(decisions.commInvestment) || decisions.commInvestment < 0 || decisions.commInvestment > 15) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_exec'), 'warning');
                    return false;
                }
                if (decisions.commInvestment > state.domainState.cash) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_cash'), 'warning');
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            return this._computeRound(state);
        }

        /* Round model. Comments stay free of quote characters (EQIL 13.1). */
        _computeRound(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var results = { period: period };
            var event = '';
            var t = function(k) { return window.mySimulation.t(k); };
            var self = this;

            if (period === 1) {
                var forceAvg = (d.rivalry + d.buyer + d.supplier + d.substitute + d.entrants) / 5;
                ds.redOceanIndex = Math.round(forceAvg * 10);
                /* Reference reading from the case evidence: rivalry and buyer power high, substitutes
                   high and rising (prefab and 3D systems), suppliers and entry barriers moderate to low. */
                var accuracy = 100;
                accuracy -= Math.abs(d.rivalry - 8.5) * 4;
                accuracy -= Math.abs(d.buyer - 7) * 4;
                accuracy -= Math.abs(d.supplier - 4) * 4;
                accuracy -= Math.abs(d.substitute - 7) * 4;
                accuracy -= Math.abs(d.entrants - 3) * 4;
                accuracy = Math.max(0, Math.min(100, Math.round(accuracy)));
                ds.diagnosisAccuracy = accuracy;
                ds.innovation = Math.round(accuracy * 0.30);
                ds.strategicCoherence = Math.round(accuracy * 0.30);
                results.redOceanIndex = ds.redOceanIndex;
                results.diagnosisAccuracy = accuracy;
                results.profit = 0;
                event = forceAvg >= 6 ? t('fb_red_ocean') : t('fb_mild_ocean');
                if (d.substitute <= 4) event += ' ' + t('fb_subst_low');
            } else if (period === 2) {
                ds.eliminate = d.eliminate;
                ds.reduce = d.reduce;
                ds.raise = d.raise;
                ds.create = d.create;
                var best = this._bestFit(ds);
                ds.strategicTheme = best.segment;
                ds.bestThemeMatches = best.net;
                var costImpact = this._costImpact(ds);
                ds.cash += costImpact;
                var funded = costImpact >= 0 ? 6 : 0;
                ds.strategicCoherence = Math.min(100, ds.strategicCoherence + best.net * 6 + funded);
                ds.innovation = Math.min(100, ds.innovation + (best.net >= 3 ? 25 : 10));
                results.eliminate = d.eliminate;
                results.reduce = d.reduce;
                results.raise = d.raise;
                results.create = d.create;
                results.themeMatches = best.net;
                results.costImpact = costImpact;
                results.profit = costImpact;
                event = best.net >= 3 ? t('fb_theme_strong') : t('fb_theme_weak');
            } else if (period === 3) {
                ds.tier = d.tier;
                ds.segment = d.segment;
                ds.tam = d.tam;
                var prof = this.PROFILES[d.segment] || null;
                var fit = prof ? this._fit(ds, prof) : { net: 0, cost: 0 };
                ds.segmentFit = fit.net;
                ds.costFit = fit.cost;
                /* Existing customers have no noncustomer tier: any tier label misreads them,
                   but the cost of that misreading arrives with the business model (round 4). */
                ds.tierCorrect = prof ? (prof.noncustomer ? prof.tier === d.tier : true) : false;
                var targetingMatch = (fit.net >= 3 ? 1 : 0) + (ds.tierCorrect ? 1 : 0);
                var expTam = this._expectedTam(d.segment);
                var tamRealism = 100 - Math.abs(d.tam - expTam) * 0.6;
                tamRealism = Math.max(0, Math.min(100, Math.round(tamRealism)));
                ds.tamRealism = tamRealism;
                ds.strategicCoherence = Math.min(100, ds.strategicCoherence + Math.max(0, fit.net) * 6 + (ds.tierCorrect ? 16 : 0));
                ds.innovation = Math.min(100, ds.innovation + (prof && prof.noncustomer ? (ds.tierCorrect ? 25 : 12) : 12));
                results.tier = d.tier;
                results.segment = d.segment;
                results.targetingMatch = targetingMatch;
                results.tamRealism = tamRealism;
                results.profit = 0;
                event = targetingMatch === 2 ? t('fb_target_match') : t('fb_target_drift');
            } else if (period === 4) {
                ds.pricing = d.pricing;
                ds.investment = d.investment;
                ds.partner = d.partner;
                ds.cash -= d.investment;
                var p4 = this.PROFILES[ds.segment] || null;
                var noncust = p4 ? p4.noncustomer : true;
                var penetration = 0.12 + 0.05 * Math.max(0, ds.segmentFit || 0);
                if (d.partner === 'partner') penetration += 0.08;
                /* Existing customers are contested: rivals already serve them and copy the offer. */
                if (!noncust) penetration *= 0.5;
                /* Capability build: concave in funding; a partner brings part of the capability. */
                var effInv = d.investment + (d.partner === 'partner' ? 10 : 0);
                var cap = Math.max(0, Math.min(1, (effInv - 5) / 20));
                var capMult = 0.2 + 0.8 * cap;
                /* Price corridor of the mass: noncustomers are priced out by a premium. */
                var volMult = noncust
                    ? (d.pricing === 'premium' ? 0.45 : d.pricing === 'discount' ? 1.15 : 1.0)
                    : (d.pricing === 'premium' ? 0.95 : d.pricing === 'discount' ? 1.05 : 1.0);
                var priceMult = d.pricing === 'premium' ? 1.2 : d.pricing === 'discount' ? 0.85 : 1.0;
                var marginPct = d.pricing === 'premium' ? 0.22 : d.pricing === 'discount' ? 0.07 : 0.14;
                marginPct += 0.015 * (ds.costFit || 0);
                if (d.partner === 'partner') marginPct -= 0.02;
                marginPct = Math.round(marginPct * 1000) / 1000;
                /* Effective, defensible TAM: as round-3 sizing realism falls, the claimed TAM is
                   pulled back toward the defensible size of the segment. */
                var realism = (typeof ds.tamRealism === 'number') ? ds.tamRealism : 100;
                var defensibleTam = this._expectedTam(ds.segment);
                var effectiveTam = defensibleTam + ((ds.tam || defensibleTam) - defensibleTam) * (realism / 100);
                if (effectiveTam < 1) effectiveTam = 1;
                var year3Revenue = Math.round(effectiveTam * penetration * capMult * volMult * priceMult);
                var year3Margin = Math.round(year3Revenue * marginPct * 10) / 10;
                ds.blueOceanRevenue = year3Revenue;
                ds.plannedRevenue = year3Revenue;
                ds.marginPct = marginPct;
                var paybackYears = (d.investment > 0 && year3Margin > 0)
                    ? Math.round((d.investment / Math.max(0.1, year3Margin)) * 10) / 10
                    : 99;
                ds.paybackYears = paybackYears;
                /* Three equal parts (concept 8.2): revenue realism, cost structure, profitability. */
                var vReal = 33 * realism / 100;
                var vCost = (marginPct >= 0.15 ? 20 : marginPct >= 0.12 ? 12 : marginPct >= 0.08 ? 5 : 0)
                          + (d.investment <= 35 ? 13 : 0);
                var vProf = (year3Margin > 0 ? 9 : 0)
                          + (paybackYears < 3 ? 15 : paybackYears < 5 ? 8 : 0)
                          + 10 * Math.min(1, Math.max(0, year3Margin) / 10);
                var viability = vReal + vCost + vProf;
                /* A discount reopens the price war: rivals retaliate on the core per-ton business. */
                if (d.pricing === 'discount') {
                    viability -= 10;
                    ds.incumbentRevenue = Math.round(ds.incumbentRevenue * 0.94);
                }
                ds.financialViability = Math.max(0, Math.min(100, Math.round(viability)));
                ds.innovation = Math.min(100, ds.innovation + (d.pricing === 'parity' ? 10 : 5));
                results.pricing = d.pricing;
                results.investment = d.investment;
                results.partner = d.partner;
                results.year3Revenue = year3Revenue;
                results.year3Margin = year3Margin;
                results.paybackYears = paybackYears;
                results.profit = Math.round((year3Margin - d.investment) * 10) / 10;
                event = ds.financialViability >= 70 ? t('fb_fin_strong')
                      : ds.financialViability >= 40 ? t('fb_fin_moderate')
                      : t('fb_fin_weak');
                if (d.pricing === 'discount') event += ' ' + t('fb_price_war');
                if (!noncust) event += ' ' + t('fb_contested');
            } else if (period === 5) {
                ds.orgDesign = d.orgDesign;
                ds.changeSpeed = d.changeSpeed;
                ds.commInvestment = d.commInvestment;
                ds.cash -= d.commInvestment;
                var exec = 0;
                if (d.orgDesign === 'separate' || d.orgDesign === 'hybrid') exec += 35;
                else exec += 10;
                if (d.changeSpeed === 'moderate') exec += 30;
                else if (d.changeSpeed === 'gradual') exec += 20;
                else exec += 10;
                if (d.commInvestment >= 3 && d.commInvestment <= 8) exec += 25;
                else if (d.commInvestment > 8) exec += 15;
                else exec += 5;
                if (ds.bestThemeMatches >= 3) exec += 10;
                /* A plan sized on an inflated market loses the board and the plants at the first review. */
                if (ds.tamRealism < 50) exec -= 15;
                ds.executionFeasibility = Math.max(0, Math.min(100, exec));
                /* Adoption: how much of the planned blue ocean revenue the organisation actually captures. */
                var adoption = 1;
                adoption *= d.changeSpeed === 'aggressive' ? 0.55 : d.changeSpeed === 'gradual' ? 0.85 : 1;
                adoption *= (d.commInvestment >= 3 && d.commInvestment <= 8) ? 1 : d.commInvestment > 8 ? 0.95 : 0.7;
                adoption *= d.orgDesign === 'integrated' ? 0.8 : 1;
                if (ds.tamRealism < 50) adoption *= 0.85;
                adoption = Math.round(adoption * 100) / 100;
                ds.adoption = adoption;
                ds.blueOceanRevenue = Math.round((ds.plannedRevenue || 0) * adoption);
                ds.financialViability = Math.max(0, Math.min(100, Math.round(ds.financialViability * (0.3 + 0.7 * adoption))));
                ds.innovation = Math.min(100, ds.innovation + 10);
                results.orgDesign = d.orgDesign;
                results.changeSpeed = d.changeSpeed;
                results.commInvestment = d.commInvestment;
                results.executionScore = ds.executionFeasibility;
                results.adoption = adoption;
                results.profit = ds.blueOceanRevenue;
                event = ds.executionFeasibility >= 80 ? t('fb_exec_excellent')
                      : ds.executionFeasibility >= 60 ? t('fb_exec_good')
                      : t('fb_exec_needs_work');
                if (adoption < 0.8) event += ' ' + t('fb_adoption_low');
            }

            var finalScore = this._composite(ds);
            ds.totalScore = finalScore;
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: finalScore });

            ds.scoreHistory.push(finalScore);
            ds.revenueHistory.push(ds.blueOceanRevenue);
            ds.coherenceHistory.push(ds.strategicCoherence);
            ds.viabilityHistory.push(ds.financialViability);
            ds.executionHistory.push(ds.executionFeasibility);
            ds.innovationHistory.push(ds.innovation);

            results.totalScore = finalScore;
            results.overallScore = finalScore;
            results.score = finalScore;
            results.event = event;

            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 400);

            return results;
        }

        _composite(ds) {
            var s = Math.round(
                ds.strategicCoherence * 0.30 +
                ds.financialViability * 0.30 +
                ds.executionFeasibility * 0.25 +
                ds.innovation * 0.15
            );
            return Math.max(0, Math.min(100, s));
        }

        _fit(ds, prof) {
            var net = 0, cost = 0;
            var e = prof.eliminate[ds.eliminate] || 0;
            var r = prof.reduce[ds.reduce] || 0;
            net += e + r + (prof.raise[ds.raise] || 0) + (prof.create[ds.create] || 0);
            cost = (e > 0 ? 1 : 0) + (r > 0 ? 1 : 0);
            return { net: Math.max(0, net), cost: cost };
        }

        _bestFit(ds) {
            var best = { segment: null, net: -1 };
            var self = this;
            Object.keys(this.PROFILES).forEach(function(name) {
                var f = self._fit(ds, self.PROFILES[name]);
                if (f.net > best.net) best = { segment: name, net: f.net };
            });
            if (best.net < 0) best.net = 0;
            return best;
        }

        _costImpact(ds) {
            var elimMap = { brand_advertising: 8, regional_offices: 12, customization: 5 };
            var redMap = { delivery_speed: 6, sales_force: 10, geo_reach: 4 };
            var raiseMap = { sustainability: -8, technical_support: -6, reliability: -4 };
            var createMap = { carbon_dashboard: -10, rural_financing: -12, modular_delivery: -8 };
            var total = 0;
            total += elimMap[ds.eliminate] || 0;
            total += redMap[ds.reduce] || 0;
            total += raiseMap[ds.raise] || 0;
            total += createMap[ds.create] || 0;
            return total;
        }

        _expectedTam(segment) {
            var p = this.PROFILES[segment];
            return p ? p.tam : 100;
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(Math.max(period - 1, 0), this.ROUNDS.length - 1);
            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');
            var briefKeys = ['brief_r1', 'brief_r2', 'brief_r3', 'brief_r4', 'brief_r5'];
            var titleKeys = ['r1_title', 'r2_title', 'r3_title', 'r4_title', 'r5_title'];
            if (titleEl && window.mySimulation) titleEl.innerHTML = window.mySimulation.t(titleKeys[idx]);
            if (textEl && window.mySimulation) textEl.innerHTML = window.mySimulation.t(briefKeys[idx]);
            var altMap = { scoreChart: 'chart_score_alt', dimensionChart: 'chart_dim_alt' };
            Object.keys(altMap).forEach(function(cid) {
                var c = document.getElementById(cid);
                if (c && window.mySimulation && c.setAttribute) c.setAttribute('aria-label', window.mySimulation.t(altMap[cid]));
            });
            for (var i = 1; i <= 5; i++) {
                var panel = document.getElementById('panelR' + i);
                if (panel) panel.style.display = (i === period) ? 'block' : 'none';
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash', function(v) {
                return '$' + Math.round(v) + 'M';
            });
            uiManager.bind('incumbentDisplay', 'domainState.incumbentRevenue', function(v) {
                return '$' + Math.round(v) + 'M';
            });
            uiManager.bind('blueOceanDisplay', 'domainState.blueOceanRevenue', function(v) {
                return '$' + Math.round(v) + 'M';
            });
            uiManager.bind('scoreDisplay', 'domainState.totalScore', function(v) {
                return Math.round(v) + ' / 100';
            });
        }

        _tx(k, fb) {
            try { var v = window.mySimulation && window.mySimulation.t ? window.mySimulation.t(k) : null; return (v && v !== k) ? v : fb; } catch (e) { return fb; }
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: this._tx('chart_score_series', 'Overall Strategy Score'),
                            data: [],
                            borderColor: '#06b6d4',
                            backgroundColor: 'rgba(6,182,212,0.14)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.25,
                            pointBackgroundColor: '#0f1c3f',
                            pointRadius: 4
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._tx('chart_score_title', 'Strategy Score Progression'), font: { size: 14, weight: '600' } }
                        },
                        scales: { y: { beginAtZero: true, max: 100 } }
                    }
                },
                dimensionChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: this._tx('dim_coherence', 'Strategic Coherence'), data: [], backgroundColor: '#0f1c3f' },
                            { label: this._tx('dim_viability', 'Financial Viability'), data: [], backgroundColor: '#0891b2' },
                            { label: this._tx('dim_execution', 'Execution Feasibility'), data: [], backgroundColor: '#06b6d4' },
                            { label: this._tx('dim_innovation', 'Innovation'), data: [], backgroundColor: '#67e8f9' }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: this._tx('chart_dim_title', 'Dimension Scores by Round'), font: { size: 14, weight: '600' } }
                        },
                        scales: { y: { beginAtZero: true, max: 100 } }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.scoreHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                },
                dimensionChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.coherenceHistory },
                        { data: state.domainState.viabilityHistory },
                        { data: state.domainState.executionHistory },
                        { data: state.domainState.innovationHistory }
                    ]
                }
            };
        }

        getHint(state, results) {
            var period = state.currentPeriod;
            if (!results) return null;
            if (period === 1 && results.diagnosisAccuracy < 60) return window.mySimulation.t('hint_r1');
            if (period === 2 && results.themeMatches < 3) return window.mySimulation.t('hint_r2');
            if (period === 3 && results.targetingMatch < 2) return window.mySimulation.t('hint_r3');
            if (period === 4 && results.paybackYears > 4) return window.mySimulation.t('hint_r4');
            if (period === 5 && results.executionScore < 60) return window.mySimulation.t('hint_r5');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.period',     label: 'Round',       i18nKey: 'col_round' },
                { key: 'results.totalScore', label: 'Round Score', i18nKey: 'col_score',
                  formatter: function(v) { return (v || 0) + ' / 100'; } },
                { key: 'results.event',      label: 'Feedback',    i18nKey: 'col_event' }
            ];
        }

        getPresets() { return null; }

        /* Run-specific mistakes, in round order, read from the stored decisions (never a play the student did not make). */
        _mistakes(ds) {
            var out = [];
            var prof = this.PROFILES[ds.segment] || null;
            var noncust = prof ? prof.noncustomer : true;
            if (ds.diagnosisAccuracy && ds.diagnosisAccuracy < 60) out.push({ round: 1, key: 'ins_diag' });
            if (ds.eliminate && ds.bestThemeMatches < 3) out.push({ round: 2, key: 'ins_grid_weak' });
            if (ds.segment && !noncust) out.push({ round: 3, key: 'ins_existing' });
            else if (ds.segment && ds.segmentFit < 3) out.push({ round: 3, key: 'ins_fit_weak' });
            if (ds.segment && noncust && !ds.tierCorrect) out.push({ round: 3, key: 'ins_tier' });
            if (ds.segment && ds.tamRealism < 70) out.push({ round: 3, key: ((ds.tam || 0) > this._expectedTam(ds.segment) ? 'ins_tam_over' : 'ins_tam_under') });
            if (ds.pricing === 'discount') out.push({ round: 4, key: 'ins_price_war' });
            if (ds.pricing === 'premium' && noncust) out.push({ round: 4, key: 'ins_premium' });
            if (ds.pricing) {
                var effInv = (ds.investment || 0) + (ds.partner === 'partner' ? 10 : 0);
                if (effInv < 20) out.push({ round: 4, key: 'ins_underfunded' });
                if ((ds.investment || 0) > 35) out.push({ round: 4, key: 'ins_overinvest' });
            }
            if (ds.changeSpeed === 'aggressive') out.push({ round: 5, key: 'ins_bigbang' });
            if (ds.changeSpeed === 'gradual') out.push({ round: 5, key: 'ins_gradual' });
            if (ds.orgDesign && (ds.commInvestment || 0) < 3) out.push({ round: 5, key: 'ins_fair_process' });
            if ((ds.commInvestment || 0) > 8) out.push({ round: 5, key: 'ins_comm_over' });
            if (ds.orgDesign === 'integrated') out.push({ round: 5, key: 'ins_integrated' });
            return out;
        }

        _tier(score) {
            /* Bands derived from the 2026-10-27 sweep: expert play 96, one real mistake 82 to 86, random median 45. */
            if (score >= 90) return 'excellent';
            if (score >= 75) return 'strong';
            if (score >= 55) return 'competent';
            return 'developing';
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var ds = window.mySimulation.state.domainState;
            var score = this._composite(ds);
            var tier = this._tier(score);
            var mistakes = this._mistakes(ds);
            var insights = [];
            for (var i = 0; i < mistakes.length && insights.length < 4; i++) insights.push(mistakes[i].key);
            var positives = [];
            if (ds.bestThemeMatches >= 3 && ds.segmentFit >= 3) positives.push('ins_ok_curve');
            if (ds.financialViability >= 70) positives.push('ins_ok_model');
            if (ds.executionFeasibility >= 70) positives.push('ins_ok_exec');
            if (ds.diagnosisAccuracy >= 80) positives.push('ins_ok_diag');
            for (var j = 0; j < positives.length && insights.length < 5; j++) {
                if (insights.length < 3 || mistakes.length === 0) insights.push(positives[j]);
            }
            if (insights.length < 3) insights.push('ins_generic_review');
            var turning = mistakes.length ? mistakes[0] : null;
            return {
                totalPeriods: history.length,
                totalScore: score,
                overallScore: score,
                composite: score,
                score: score,
                strategicCoherence: ds.strategicCoherence,
                financialViability: ds.financialViability,
                executionFeasibility: ds.executionFeasibility,
                innovation: ds.innovation,
