                turningPointRound: turning ? turning.round : 0,
                turningPointKey: turning ? turning.key : 'tp_none',
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = function(k) { return window.mySimulation ? window.mySimulation.t(k) : k; };
            var tr = function(v) { var o = t(v); return (typeof o === 'string' && o.length) ? o : v; };
            var ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var lang = (window.vcI18n && window.vcI18n._lang) || document.documentElement.lang || 'en';
            var fmt = function(v) { var n = Math.round(Number(v) || 0); return String(n); };
            var score = summary.overallScore != null ? summary.overallScore : this._composite(ds);
            var tierKey = summary.performanceKey || ('tier_' + this._tier(score));
            var kpi = function(labelKey, value) {
                return '<div class="blueshift-cm-kpi"><div class="blueshift-cm-kpi-label">' + tr(labelKey) + '</div><div class="blueshift-cm-kpi-value">' + value + '</div></div>';
            };
            var adoptionPct = Math.round((summary.adoption != null ? summary.adoption : (ds.adoption || 0)) * 100);
            var html = '';
            html += '<div class="blueshift-cm" role="region" aria-label="' + tr('cm_title') + '" lang="' + lang + '">';
            html += '<div class="blueshift-cm-head"><div class="blueshift-cm-score">' + fmt(score) + '<span>/100</span></div>';
            html += '<div class="blueshift-cm-tier">' + tr(tierKey) + '</div></div>';
            html += '<div class="blueshift-cm-kpis">';
            html += kpi('dim_coherence', fmt(summary.strategicCoherence != null ? summary.strategicCoherence : ds.strategicCoherence));
            html += kpi('dim_viability', fmt(summary.financialViability != null ? summary.financialViability : ds.financialViability));
            html += kpi('dim_execution', fmt(summary.executionFeasibility != null ? summary.executionFeasibility : ds.executionFeasibility));
            html += kpi('dim_innovation', fmt(summary.innovation != null ? summary.innovation : ds.innovation));
            html += kpi('cm_revenue', '$' + fmt(summary.blueOceanRevenue != null ? summary.blueOceanRevenue : ds.blueOceanRevenue) + 'M / $' + fmt(summary.plannedRevenue != null ? summary.plannedRevenue : ds.plannedRevenue) + 'M');
            html += kpi('cm_adoption', adoptionPct + '%');
            html += '</div>';
            var tpKey = summary.turningPointKey || 'tp_none';
            html += '<h4 class="blueshift-cm-h">' + tr('cm_turning') + '</h4>';
            if (summary.turningPointRound) {
                html += '<p class="blueshift-cm-tp"><strong>' + tr('round_label') + ' ' + summary.turningPointRound + ':</strong> ' + tr(tpKey + '_name') + '.</p>';
            } else {
                html += '<p class="blueshift-cm-tp">' + tr('tp_none') + '</p>';
            }
            var list = Array.isArray(summary.insights) ? summary.insights : [];
            html += '<h4 class="blueshift-cm-h">' + tr('cm_insights') + '</h4><ul class="blueshift-cm-list">';
            for (var i = 0; i < list.length; i++) {
                html += '<li>' + tr(list[i]) + '</li>';
            }
            html += '</ul>';
            html += '<h4 class="blueshift-cm-h">' + tr('cm_questions') + '</h4><ol class="blueshift-cm-list">';
            html += '<li>' + tr('dq1') + '</li><li>' + tr('dq2') + '</li><li>' + tr('dq3') + '</li></ol>';
            html += '</div>';
            return html;
        }

